 */
export function rewriteSystemBlocksForModel(blocks, modelId) {
    if (!modelId)
        return blocks;
    const display = deriveModelDisplayName(modelId);
    return blocks.map((block) => {
        if (block?.type !== "text" || typeof block.text !== "string")
            return block;
        let text = block.text;
        text = text.replace(/You are powered by the model named [^\n]+? The exact model ID is [a-z0-9.-]+\./g, `You are powered by the model named ${display}. The exact model ID is ${modelId}.`);
